TEST(CeltFilter, CombMatchesReference) {
    constexpr int kHistory = 1032;
    uint32_t state = 0x5eed1234u;
    auto next = [&state]() {
        state = state * 1664525u + 1013904223u;
        return static_cast<float>(static_cast<int32_t>(state >> 8) % 20001 - 10000) /
               10000.0f;
    };
    for (const CombCase& test : kCombCases) {
        std::vector<float> buf(kHistory + test.n);
        for (float& value : buf) {
            value = next();
        }
        player::audio::opus::combFilter(buf.data() + kHistory, buf.data() + kHistory,
                                       test.t0, test.t1, test.n, test.g0, test.g1,
                                       test.tapset0, test.tapset1,
                                       player::audio::opus::kCeltWindow, test.overlap);
        for (int i = 0; i < test.n; ++i) {
            EXPECT_NEAR(buf[kHistory + i], test.out[i], 1e-5f) << "out " << i;
        }
    }
}

TEST(CeltFilter, DeemphasisMatchesReference) {
    uint32_t state = 0x5eed1234u;
    auto next = [&state]() {
        state = state * 1664525u + 1013904223u;
        return static_cast<float>(static_cast<int32_t>(state >> 8) % 20001 - 10000) /
               10000.0f;
    };
    // Skip the comb cases' inputs to stay in sync with the oracle.
    for (int i = 0; i < 7080; ++i) {
        next();
    }
    for (const DeempCase& test : kDeempCases) {
        std::vector<std::vector<float>> in(test.channels, std::vector<float>(test.n));
        for (auto& channel : in) {
            for (float& value : channel) {
                value = next();
            }
        }
        std::vector<float> mem(test.channels);
        for (float& value : mem) {
            value = next();
        }
        std::vector<float*> ptrs(test.channels);
        for (int c = 0; c < test.channels; ++c) {
            ptrs[c] = in[c].data();
        }
        std::vector<float> pcm(test.channels * (test.n / test.downsample));
        player::audio::opus::deemphasis(ptrs.data(), pcm.data(), test.n, test.channels,
                                         test.downsample,
                                         player::audio::opus::kCeltPreemph48k,
                                         mem.data());
        for (int i = 0; i < static_cast<int>(pcm.size()); ++i) {
            EXPECT_NEAR(pcm[i], test.pcm[i], 1e-5f) << "pcm " << i;
        }
        for (int c = 0; c < test.channels; ++c) {
            EXPECT_NEAR(mem[c], test.mem[c], 1e-5f) << "mem " << c;
        }
    }
}
